"""Unit test for the raw chunk download script (T002).

The test checks that the Parquet file produced by ``code.data.download``
contains non‑empty ``content`` fields and the expected number of rows per
language (1 000 each).
"""

import hashlib
from pathlib import Path

import pandas as pd
import pytest

from llmxive_toolkit import paths

# The script under test is executed as part of the task's execution step,
# so we only validate the artefacts it should have produced.

@pytest.fixture(scope="module")
def raw_parquet_path() -> Path:
    """Path to the Parquet file generated by the download script."""
    return paths.data("processed", "raw_chunks.parquet")

def test_parquet_exists(raw_parquet_path: Path):
    assert raw_parquet_path.is_file(), f"{raw_parquet_path} does not exist"

def test_row_counts_per_language(raw_parquet_path: Path):
    df = pd.read_parquet(raw_parquet_path)
    # Expect exactly 1 000 rows for each of the two target languages.
    counts = df["language"].value_counts()
    assert counts.get("Python", 0) == 1000, "Python row count mismatch"
    assert counts.get("Java", 0) == 1000, "Java row count mismatch"

def test_content_not_empty(raw_parquet_path: Path):
    df = pd.read_parquet(raw_parquet_path)
    # The ``content`` column must contain non‑empty strings.
    non_empty = df["content"].apply(lambda x: isinstance(x, str) and len(x.strip()) > 0)
    avg_len = df["content"].apply(lambda x: len(str(x))).mean()
    assert non_empty.all(), "Found empty or non‑string content entries"
    assert avg_len > 0, f"Average content length is {avg_len}, expected > 0"

def test_checksum_matches(raw_parquet_path: Path):
    checksum_file = paths.data("checksums.txt")
    assert checksum_file.is_file(), "Checksum file missing"
    # Compute current checksum
    sha256 = hashlib.sha256()
    with open(raw_parquet_path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            sha256.update(chunk)
    current = sha256.hexdigest()
    # Read recorded checksum
    recorded = None
    with open(checksum_file, "r") as f:
        for line in f:
            if raw_parquet_path.name in line:
                recorded = line.split()[0]
                break
    assert recorded is not None, "Checksum entry not found"
    assert recorded == current, "Checksum mismatch for raw_chunks.parquet"